Class RelocCode (RL : Reloc) := { rl_code_ok : code_check rl_segs rl_delta canon_code = true }.

Lemma rl_fetch : forall {RL : Reloc} {RC : RelocCode RL} b c (w : bv 32),
  code_has canon_code b c (bv_unsigned w) = true -> fetch_word rl_segs (rl (rl_delta b) c) = Some w.
Proof.
ltac2:(KReplay.run1 (kr_t_CanonCode ()) [] "h01Hh12RCh22RLh31bh41ch51wp;1p;2p;4p;3p;8g0000j1:Tg0017j10Tg001\j12Tg002:j11Tg002]j29Tg003Gj48Tg004Kj33Tg004ej14Tg005dj15Tg006dj26Tg007jj87Tg0090f0R0#:g009og00:Tg00;2#0#0#0#0#0#2R1#1g00;Wg00<7R2f2R3f1R41910C8g00==33f5R1#4%51P2f3P3P4f4,61P0G7W0W5W4W3W1W2o"). Qed.

Lemma rl_fetch_at : forall {RL : Reloc} {RC : RelocCode RL} (i : nat) (ch : cchunk) c (w : bv 32),
  nth_error canon_code i = Some ch -> chunk_has ch c (bv_unsigned w) = true ->
  fetch_word rl_segs (rl (rl_delta (cc_blk ch)) c) = Some w.
